WITH store_item_loss AS ( SELECT s.s_store_id, s.s_store_name, i.i_item_id, i.i_product_name, SUM(sr.sr_net_loss) AS total_net_loss, AVG(sr.sr_return_quantity) AS avg_return_qty FROM store_returns sr JOIN store s ON sr.sr_store_sk = s.s_store_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk WHERE sr.sr_return_amt > 0 GROUP BY s.s_store_id, s.s_store_name, i.i_item_id, i.i_product_name ) SELECT * FROM ( SELECT s_store_id, s_store_name, i_item_id, i_product_name, total_net_loss, avg_return_qty, ROW_NUMBER() OVER (PARTITION BY s_store_id ORDER BY avg_return_qty DESC) AS qty_rank FROM store_item_loss ) t WHERE qty_rank <= 3 ORDER BY s_store_id, qty_rank
